 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_companyname = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchSubcomList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00033.__on_enter_2_ipt_companyName' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchSubcomList
 * @description search Subcom List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchSubcomList = async function () {
    const sbmOptions = {
        id: "tx_searchSubcomList",
        method: "post",
        action: "/submission/corpList.do?method=searchSubcomList",
        ref: "dma_searchSubcomListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchSubcomListByBeginIndex
 * @description search Subcom List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchSubcomListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchSubcomListByBeginIndex",
        method: "post",
        action: "/submission/corpList.do?method=searchSubcomList",
        ref: "dma_searchSubcomListByBeginIndexReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchSubcomList
 * @description search Subcom List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSubcomList = async function () {
    scwin.clearBtnImage();
    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "");
    (document.corpListForm || { elements: [] }).target = "iframe";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchSubcomList";
    await scwin.tx_searchSubcomList();
};

/**
 * @method
 * @name searchSubcomListByBeginIndex
 * @description search Subcom List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSubcomListByBeginIndex = async function () {
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchSubcomList";
    (document.corpListForm || { elements: [] }).target = "iframe";
    await scwin.tx_searchSubcomListByBeginIndex();
};

/**
 * @method
 * @name swapImage
 * @description swap Image 처리
 * @param {Object} obj 컴포넌트
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.swapImage = function (obj, no) {
    $c.util.getComponent('dma_searchSubcomListReq').set('pageIndex', 1);
    scwin.clearBtnImage();
    // TODO Stage2(규칙 19): jQuery — 표시/스타일 → show/hide/setStyle/addClass(컴포넌트 API)
    $(obj).addClass("mga_5");
    const frm = (document.corpListForm || { elements: [] });
    if (no === "01") {
        $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "A");
    } else {
        if (no === "02") {
            $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "B");
        } else {
            if (no === "03") {
                $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "C");
            } else {
                if (no === "04") {
                    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "D");
                } else {
                    if (no === "05") {
                        $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "E");
                    } else {
                        if (no === "06") {
                            $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "F");
                        } else {
                            if (no === "07") {
                                $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "G");
                            } else {
                                if (no === "08") {
                                    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "H");
                                } else {
                                    if (no === "09") {
                                        $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "I");
                                    } else {
                                        if (no === "10") {
                                            $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "J");
                                        } else {
                                            if (no === "11") {
                                                $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "K");
                                            } else {
                                                if (no === "12") {
                                                    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "L");
                                                } else {
                                                    if (no === "13") {
                                                        $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "M");
                                                    } else {
                                                        if (no === "14") {
                                                            $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "N");
                                                        } else {
                                                            if (no === "18") {
                                                                $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "AZ");
                                                            } else {
                                                                if (no === "17") {
                                                                    $c.util.getComponent('dma_searchSubcomListReq').set('beginIndex', "ETC");
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name clearBtnImage
 * @description clear Btn Image 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearBtnImage = function () {
    // TODO Stage2(규칙 19): jQuery — DOM 탐색 → 대상 컴포넌트 직접 참조/DataList 루프
    $("#phoneme").children("a").each(function() {
            // TODO Stage2(규칙 19): jQuery — 표시/스타일 → show/hide/setStyle/addClass(컴포넌트 API)
            $(this).removeClass("mga_5");
    });
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).setCorpInfo === 'function' ? (scwin.openerScwin()).setCorpInfo(isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, returnKey) : void 0), $c.win.closePopup([{ __sdd_rec: 1, isurCd: isurCd, kisComCd: kisComCd, repIsuSrtCd: repIsuSrtCd, comNm: comNm, comAbbrv: comAbbrv, isurSymbl: isurSymbl, fssUnqNo: fssUnqNo, returnKey: returnKey }]));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00033' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
